# Generate WebCore's SVG/XLINK name tables and SVGElementFactory from the checked-in
# .in files (ksvg2/scripts/make_names.pl).  The outputs live next to the other
# generated sources (src/webcore/buildKJS), which the build globs into SOURCES.
#
# Why this exists: the vendored tree ships *stub* SVGNames.cpp / SVGElementFactory.cpp
# (they were generated by the "SVG disabled" branch of the old DerivedSources.make).
# Enabling ENABLE_SVG needs the real tables again.  Re-run this script whenever
# ksvg2/svg/svgtags.in or svgattrs.in change.
#
# The .in files are CRLF; make_names.pl chomps only the \n, so the generated names
# used to come out as "a<CR>Tag".  Inputs are copied to LF-only temp files first.
#
# Usage:
#   pwsh -File tools/gen_svg_names.ps1              # SVG + XLink names only
#   pwsh -File tools/gen_svg_names.ps1 -WithCSS     # also regenerate CSS name tables
#                                                   # (finds gperf in vcpkg or PATH)
param(
    [switch]$WithCSS
)

$ErrorActionPreference = 'Stop'

function Find-Perl {
    $cmd = Get-Command perl.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    foreach ($p in @('C:\Program Files\Git\usr\bin\perl.exe',
                     'H:\installed\msys64\usr\bin\perl.exe',
                     'C:\msys64\usr\bin\perl.exe')) {
        if (Test-Path $p) { return $p }
    }
    throw 'perl.exe not found (needed by make_names.pl)'
}

function Find-Gperf {
    $cmd = Get-Command gperf.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    foreach ($p in @('H:\installed\vcpkg_\installed\x64-windows\tools\gperf\gperf.exe',
                     'H:\installed\vcpkg_\packages\gperf_x64-windows\tools\gperf\gperf.exe',
                     'C:\vcpkg\installed\x64-windows\tools\gperf\gperf.exe')) {
        if (Test-Path $p) { return $p }
    }
    return $null
}

# Forward-slash paths: make_names.pl hands them to the C preprocessor, which eats
# Windows backslashes.
function Fwd([string]$p) { return $p.Replace('\', '/') }

function Normalize-Lf([string]$src, [string]$dst) {
    $text = [string](Get-Content -LiteralPath $src -Raw)
    $text = $text.Replace("`r`n", "`n").Replace("`r", "`n")
    [IO.File]::WriteAllText($dst, $text, (New-Object System.Text.UTF8Encoding($false)))
}

$root = Split-Path -Parent $PSScriptRoot
$perl = Find-Perl
$out  = Join-Path $root 'src/webcore/buildKJS'
$gen  = Join-Path $root 'src/webcore/ksvg2/scripts/make_names.pl'

if (-not (Test-Path $out)) { throw "output dir missing: $out" }

$tmp = Join-Path $env:TEMP ('agave_svg_gen_' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Force -Path $tmp | Out-Null

try {
    $svgTagsLf   = Join-Path $tmp 'svgtags.in'
    $svgAttrsLf  = Join-Path $tmp 'svgattrs.in'
    $xlinkAttrsLf = Join-Path $tmp 'xlinkattrs.in'
    Normalize-Lf (Join-Path $root 'src/webcore/ksvg2/svg/svgtags.in') $svgTagsLf
    Normalize-Lf (Join-Path $root 'src/webcore/ksvg2/svg/svgattrs.in') $svgAttrsLf
    Normalize-Lf (Join-Path $root 'src/webcore/ksvg2/misc/xlinkattrs.in') $xlinkAttrsLf

    Push-Location $out
    try {
        & $perl (Fwd $gen) --tags (Fwd $svgTagsLf) --attrs (Fwd $svgAttrsLf) `
            --namespace SVG --cppNamespace WebCore --namespaceURI 'http://www.w3.org/2000/svg' `
            --factory --attrsNullNamespace --output .
        if ($LASTEXITCODE -ne 0) { throw 'make_names.pl (SVG) failed' }

        & $perl (Fwd $gen) --attrs (Fwd $xlinkAttrsLf) `
            --namespace XLink --cppNamespace WebCore --namespaceURI 'http://www.w3.org/1999/xlink' `
            --output .
        if ($LASTEXITCODE -ne 0) { throw 'make_names.pl (XLink) failed' }
    } finally {
        Pop-Location
    }

    # make_names.pl reads the preprocessor's pipe in a mode that leaves CR bytes
    # on each name ("a\rTag"), which broke the generated headers.  The generator
    # only ever emits real line breaks as \n, so dropping CRs is safe.
    foreach ($name in @('SVGNames.h', 'SVGNames.cpp', 'XLinkNames.h', 'XLinkNames.cpp',
                        'SVGElementFactory.h', 'SVGElementFactory.cpp')) {
        $file = Join-Path $out $name
        if (Test-Path $file) {
            $text = [IO.File]::ReadAllText($file).Replace("`r", "")
            [IO.File]::WriteAllText($file, $text, (New-Object System.Text.UTF8Encoding($false)))
        }
    }

    if ($WithCSS) {
        $gperf = Find-Gperf
        if (-not $gperf) { throw '-WithCSS needs gperf.exe (vcpkg or PATH)' }
        $savedPath = $env:PATH
        $env:PATH = (Split-Path -Parent $gperf) + ';' + $env:PATH
        try {
            # CSSPropertyNames: base list + SVG additions (DerivedSources.make did the same cat)
            $cssDir = Join-Path $tmp 'css'
            New-Item -ItemType Directory -Force -Path $cssDir | Out-Null
            Normalize-Lf (Join-Path $root 'src/webcore/css/CSSPropertyNames.in') (Join-Path $cssDir 'CSSPropertyNames.in')
            Normalize-Lf (Join-Path $root 'src/webcore/ksvg2/css/SVGCSSPropertyNames.in') (Join-Path $cssDir 'svgprops.in')
            $props = [IO.File]::ReadAllText((Join-Path $cssDir 'CSSPropertyNames.in')) +
                     [IO.File]::ReadAllText((Join-Path $cssDir 'svgprops.in'))
            [IO.File]::WriteAllText((Join-Path $cssDir 'CSSPropertyNames.in'), $props, (New-Object System.Text.UTF8Encoding($false)))

            # CSSValueKeywords: SVG additions are lower-cased (CSS values are case-insensitive)
            Normalize-Lf (Join-Path $root 'src/webcore/css/CSSValueKeywords.in') (Join-Path $cssDir 'CSSValueKeywords.in')
            Normalize-Lf (Join-Path $root 'src/webcore/ksvg2/css/SVGCSSValueKeywords.in') (Join-Path $cssDir 'svgvalues.in')
            $values = [IO.File]::ReadAllText((Join-Path $cssDir 'CSSValueKeywords.in')) +
                      ([IO.File]::ReadAllText((Join-Path $cssDir 'svgvalues.in'))).ToLower()
            [IO.File]::WriteAllText((Join-Path $cssDir 'CSSValueKeywords.in'), $values, (New-Object System.Text.UTF8Encoding($false)))

            Push-Location $cssDir
            try {
                & $perl (Fwd (Join-Path $root 'src/webcore/css/makeprop.pl'))
                if ($LASTEXITCODE -ne 0) { throw 'makeprop.pl failed' }
                & $perl (Fwd (Join-Path $root 'src/webcore/css/makevalues.pl'))
                if ($LASTEXITCODE -ne 0) { throw 'makevalues.pl failed' }
            } finally {
                Pop-Location
            }

            foreach ($name in @('CSSPropertyNames.in', 'CSSPropertyNames.h', 'CSSPropertyNames.gperf', 'CSSPropertyNames.c',
                                'CSSValueKeywords.in', 'CSSValueKeywords.h', 'CSSValueKeywords.gperf', 'CSSValueKeywords.c')) {
                $srcFile = Join-Path $cssDir $name
                if (Test-Path $srcFile) { Copy-Item $srcFile (Join-Path $out $name) -Force }
            }
        } finally {
            $env:PATH = $savedPath
        }
    }
} finally {
    Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
}

Get-ChildItem $out -File |
    Where-Object { $_.Name -match '^(SVG|XLink)Names|^SVGElementFactory|^CSS(PropertyNames|ValueKeywords)\.(h|c|gperf|in)$' } |
    Sort-Object Name |
    ForEach-Object { '{0} {1} bytes' -f $_.Name, $_.Length }
